from fastapi.responses import HTMLResponse


def index_page() -> HTMLResponse:
    return HTMLResponse(r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MedRAG</title><style>
:root{--ink:#102a43;--muted:#627d98;--line:#d9e2ec;--bg:#f5f8fc;--blue:#1479d1;--teal:#07828d;--shadow:0 14px 40px #16385715}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px Inter,system-ui,sans-serif;line-height:1.55}.shell{max-width:1200px;margin:auto;padding:0 28px}.top{height:74px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:20px;font-weight:800;display:flex;align-items:center;gap:10px}.mark{display:grid;place-items:center;width:35px;height:35px;border-radius:11px;background:linear-gradient(135deg,var(--blue),var(--teal));color:white;font-size:22px}.badge,.state,.step{border-radius:99px;padding:5px 10px;font-size:11px;font-weight:750}.badge{background:#e2f5f3;color:#057070}.hero{padding:27px 0}.eyebrow{font-size:11px;color:var(--teal);letter-spacing:1.2px;font-weight:800;text-transform:uppercase}.hero h1{font-size:clamp(31px,4vw,48px);line-height:1.08;letter-spacing:-1.7px;margin:8px 0}.hero p{font-size:17px;color:var(--muted);margin:0}.card{background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow)}.search{padding:21px}.search label{display:flex;justify-content:space-between;font-weight:750;margin-bottom:9px}.muted{color:var(--muted);font-weight:500}textarea{width:100%;height:105px;border:1px solid #b8c8d8;border-radius:12px;padding:13px;font:inherit;resize:vertical;outline:none}textarea:focus{border-color:var(--blue);box-shadow:0 0 0 4px #dceeff}.actions{display:flex;justify-content:space-between;gap:12px;margin-top:13px}.key{border:0;border-bottom:1px solid var(--line);min-width:220px;font:13px inherit;outline:none}button{border:0;border-radius:10px;padding:11px 17px;background:var(--blue);color:#fff;font:700 14px inherit;cursor:pointer;box-shadow:0 7px 15px #cce3f7}button:disabled{opacity:.7}.examples{font-size:13px;color:var(--muted);margin-top:14px}.chip{display:inline-block;margin:2px 0 2px 5px;padding:4px 9px;border:1px solid #d2e6f4;border-radius:99px;color:#285c86;background:#f2f8fc;cursor:pointer}.grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px;margin:24px 0}.result{padding:24px}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #edf2f7;padding-bottom:14px;margin-bottom:15px}.head h2,.panel h2{font-size:17px;margin:0}.state{background:#e2f5ef;color:#08705e}.summary-tools{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;font-size:12px;color:var(--muted)}.link{background:#fff;color:var(--blue);box-shadow:none;border:1px solid #cfe5f4;padding:6px 9px;font-size:12px}.claim{margin:9px 0;padding:13px;border:1px solid #e1edf5;border-left:4px solid var(--teal);border-radius:10px;background:#fcfeff;line-height:1.7}.cite{padding:3px 6px;background:#e4f3fb;color:#0c608d;box-shadow:none;font-size:11px;margin-left:3px}.empty{height:215px;display:grid;place-items:center;text-align:center;color:var(--muted)}.notice{margin-top:20px;padding:11px;background:#fff8e6;color:#765700;border-radius:9px;font-size:12px}.side{display:grid;gap:16px;align-content:start}.panel{padding:18px}.panel p{font-size:12px;color:var(--muted);margin:4px 0 12px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metric{padding:10px;border:1px solid #e3edf5;border-radius:10px}.metric b{display:block;font-size:18px}.metric span{font-size:11px;color:var(--muted)}.barrow{margin:10px 0}.barlabel{display:flex;justify-content:space-between;font-size:12px;color:var(--muted)}.bar{height:8px;background:#e8eef3;border-radius:9px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,var(--blue),var(--teal))}.steps{display:flex;flex-wrap:wrap;gap:5px}.step{background:#eef7fb;color:#185779}.evidence{grid-column:1/-1;padding:18px;overflow:auto}.evidence h2{font-size:17px;margin:0 0 3px}.evidence p{margin:0 0 12px;color:var(--muted);font-size:13px}table{width:100%;min-width:680px;border-collapse:collapse;font-size:13px}th,td{padding:11px;border-bottom:1px solid #edf2f7;text-align:left;vertical-align:top}th{font-size:10px;letter-spacing:.5px;text-transform:uppercase;color:var(--muted);background:#f7fafc}td a{font-weight:700;color:var(--ink);text-decoration:none}.excerpt{max-width:400px;color:var(--muted);font-size:12px}.flash{animation:flash 1.4s}@keyframes flash{50%{background:#fff3bf}}.error{padding:13px;background:#fff0f0;color:#9e1d1d;border-radius:9px}@media(max-width:1000px){.shell{padding:0 22px}.grid{grid-template-columns:minmax(0,1fr) 280px}}@media(max-width:780px){.shell{padding:0 16px}.top{height:66px}.hero{padding:22px 0}.hero h1{font-size:34px}.grid{grid-template-columns:1fr;margin:18px 0}.side{grid-template-columns:1fr 1fr}.side .panel:last-child{grid-column:1/-1}.actions{flex-direction:column}.key{width:100%;min-width:0;height:40px}.actions button{min-height:46px}.result{padding:18px}.evidence{grid-column:auto;padding:14px}}@media(max-width:520px){.shell{padding:0 12px}.brand{font-size:18px}.top .badge:last-child{display:none}.hero h1{font-size:30px}.hero p{font-size:15px}.search,.result{padding:15px;border-radius:15px}.side{grid-template-columns:1fr}.side .panel:last-child{grid-column:auto}.summary-tools{align-items:flex-start;flex-direction:column;gap:8px}.claim{padding:11px;border-left-width:3px;font-size:14px}.cite{min-height:28px}.evidence{border-radius:15px}th,td{padding:9px}.notice{font-size:11px}}</style></head><body><main class="shell"><header class="top"><div class="brand"><span class="mark">+</span>MedRAG <span class="badge">Evidence research</span></div><span class="badge">Public sources only</span></header><section class="hero"><div class="eyebrow">Clinical literature, made navigable</div><h1>Evidence, organized for decisions.</h1><p>Source-grounded medical literature summaries with transparent agent steps and retrieval quality.</p></section><section class="card search"><label for="q">What would you like to research? <span id="counter" class="muted">0 / 1500</span></label><textarea id="q" maxlength="1500" placeholder="What does the evidence say about annual influenza vaccination?"></textarea><div class="actions"><input class="key" id="key" type="password" placeholder="App API key (if required)"><button id="go">Analyze evidence →</button></div><div class="examples">Try: <span class="chip">Flu vaccine recommendation</span><span class="chip">Do antibiotics treat influenza?</span><span class="chip">Type 2 diabetes prevention</span></div></section><section class="grid"><article class="card result"><div class="head"><h2>Evidence summary</h2><span id="state" class="state">Ready</span></div><div id="tools" class="summary-tools" hidden><span id="claim-count"></span><button id="expand" class="link">Show all findings</button></div><div id="answer" class="empty">Ask a research question to generate an evidence brief.</div><div class="notice">For public-literature research only — not medical advice. Do not enter personal health information.</div></article><aside class="side"><section class="card panel"><h2>Research overview</h2><p>Generated from the current response.</p><div id="metrics" class="metrics"></div></section><section class="card panel"><h2>Source relevance</h2><p>Reranked relevance by source.</p><div id="chart" class="muted">No results yet.</div></section><section class="card panel"><h2>Agent workflow</h2><p>Inspectable research pipeline.</p><div id="agents" class="steps"><span class="step">Waiting</span></div></section></aside><section class="card evidence"><h2>Evidence map</h2><p>Click a citation in the summary to jump to its supporting source.</p><table><thead><tr><th>Source</th><th>Organization</th><th>Published</th><th>Score</th><th>Excerpt</th></tr></thead><tbody id="rows"><tr><td colspan="5" class="muted">No evidence retrieved.</td></tr></tbody></table></section></section></main><script>
const q=document.querySelector('#q'),go=document.querySelector('#go'),answer=document.querySelector('#answer'),state=document.querySelector('#state'),tools=document.querySelector('#tools'),expand=document.querySelector('#expand');let claims=[],all=false;const el=(t,x)=>{const n=document.createElement(t);n.textContent=x;return n};q.oninput=()=>document.querySelector('#counter').textContent=`${q.value.length} / 1500`;document.querySelectorAll('.chip').forEach(c=>c.onclick=()=>{q.value=c.textContent;q.oninput();q.focus()});function jump(n){const row=document.querySelector(`#source-${n}`);if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.classList.remove('flash');void row.offsetWidth;row.classList.add('flash')}}function card(text){const d=document.createElement('article');d.className='claim';let p=0;for(const m of text.matchAll(/\[(\d+)]/g)){d.append(document.createTextNode(text.slice(p,m.index)));const b=el('button',m[0]);b.className='cite';b.onclick=()=>jump(m[1]);d.append(b);p=m.index+m[0].length}d.append(document.createTextNode(text.slice(p)));return d}function show(){answer.replaceChildren(...claims.slice(0,all?claims.length:3).map(card));expand.textContent=all?'Show fewer findings':'Show all findings'}expand.onclick=()=>{all=!all;show()};function render(d){claims=d.answer.split(/(?<=\])\s+/).filter(Boolean);all=false;tools.hidden=false;document.querySelector('#claim-count').textContent=`${claims.length} evidence-backed finding${claims.length===1?'':'s'}`;show();state.textContent=d.status.replaceAll('_',' ');const metric=document.querySelector('#metrics');metric.replaceChildren(...[[d.sources.length,'Sources'],[d.verification_status,'Verification'],[d.generation_mode,'Generation'],[d.planned_queries.length,'Queries']].map(x=>{const e=document.createElement('div');e.className='metric';e.append(el('b',x[0]),el('span',x[1]));return e}));const chart=document.querySelector('#chart');chart.replaceChildren(...d.sources.map((s,i)=>{const r=document.createElement('div');r.className='barrow';const l=document.createElement('div');l.className='barlabel';l.append(el('span',`[${i+1}] ${s.organization}`),el('b',`${Math.round(s.score*100)}%`));const bar=document.createElement('div'),fill=document.createElement('div');bar.className='bar';fill.className='fill';fill.style.width=`${Math.max(4,s.score*100)}%`;bar.append(fill);r.append(l,bar);return r}));document.querySelector('#agents').replaceChildren(...d.agent_trace.map(a=>el('span',`${a.agent}: ${a.outcome}`)));const rows=document.querySelector('#rows');rows.replaceChildren(...d.sources.map((s,i)=>{const tr=document.createElement('tr');tr.id=`source-${i+1}`;const t=document.createElement('td'),a=el('a',`[${i+1}] ${s.title}`);a.href=s.url;a.target='_blank';a.rel='noreferrer';t.append(a);const cells=[t,el('td',s.organization),el('td',s.published_on),el('td',`${Math.round(s.score*100)}%`),el('td',s.excerpt)];cells[4].className='excerpt';tr.append(...cells);return tr}))}async function ask(){if(q.value.trim().length<5){q.focus();return}go.disabled=true;go.textContent='Analyzing…';state.textContent='Researching';tools.hidden=true;try{const h={'Content-Type':'application/json'},key=document.querySelector('#key').value.trim();if(key)h['X-API-Key']=key;const r=await fetch('/v1/ask',{method:'POST',headers:h,body:JSON.stringify({question:q.value.trim(),max_sources:5})}),d=await r.json();if(!r.ok)throw Error(d.detail||'Request failed');render(d)}catch(e){answer.className='error';answer.textContent=e.message;state.textContent='Needs attention'}finally{go.disabled=false;go.textContent='Analyze evidence →'}}go.onclick=ask;q.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')ask()};</script></body></html>""")
